    private static SerializedProperty GetRefIds(SerializedObject so)
    {
        SerializedProperty refs = so.FindProperty("references");
        return refs?.FindPropertyRelative("RefIds");
    }

    private static void WireInteractorActions(
        Component interactor,
        Component primary,
        Component secondary,
        string primaryMethod,
        string secondaryMethod)
    {
        SerializedObject so = new SerializedObject(interactor);
        SerializedProperty refIds = GetRefIds(so);
        if (refIds == null)
        {
            return;
        }

        for (int i = 0; i < refIds.arraySize; i++)
        {
            SerializedProperty data = refIds.GetArrayElementAtIndex(i).FindPropertyRelative("data");
            if (data == null)
            {
                continue;
            }

            SerializedProperty varName = data.FindPropertyRelative("varName");
            if (varName == null || varName.stringValue != "ButtonConfigs")
            {
                continue;
            }

            SerializedProperty buttonData = data.FindPropertyRelative("Data");
            if (buttonData == null || !buttonData.isArray || buttonData.arraySize == 0)
            {
                continue;
            }

            SerializedProperty firstButton = buttonData.GetArrayElementAtIndex(0);
            SerializedProperty actions = firstButton.FindPropertyRelative("ButtonActions");
            if (actions == null)
            {
                continue;
            }

            actions.arraySize = secondary != null && !string.IsNullOrEmpty(secondaryMethod) ? 2 : 1;

            SetButtonAction(actions.GetArrayElementAtIndex(0), primary, primaryMethod);
            if (actions.arraySize > 1 && secondary != null)
            {
                SetButtonAction(actions.GetArrayElementAtIndex(1), secondary, secondaryMethod);
            }

            so.ApplyModifiedProperties();
            return;
        }
    }

    private static void SetButtonAction(SerializedProperty action, Component target, string methodName)
    {
        SerializedProperty dataRef = action.FindPropertyRelative("Data");
        if (dataRef != null)
        {
            dataRef.objectReferenceValue = target;
        }

        SerializedProperty method = action.FindPropertyRelative("methodName");
        if (method != null)
        {
            method.stringValue = methodName;
        }
    }

    private static void SetInteractorButtonText(Component interactor, string text)
    {
        SerializedObject so = new SerializedObject(interactor);
        SerializedProperty refIds = GetRefIds(so);
        if (refIds == null)
        {
            return;
        }

        foreach (SerializedProperty entry in IterateRefIds(refIds))
        {
            SerializedProperty data = entry.FindPropertyRelative("data");
            if (data == null)
            {
                continue;
            }

            SerializedProperty varName = data.FindPropertyRelative("varName");
            if (varName == null || varName.stringValue != "ButtonConfigs")
            {
                continue;
            }

            SerializedProperty buttonData = data.FindPropertyRelative("Data");
            if (buttonData == null || !buttonData.isArray || buttonData.arraySize == 0)
            {
                continue;
            }

            SerializedProperty textProp = buttonData.GetArrayElementAtIndex(0).FindPropertyRelative("Text");
            if (textProp != null)
            {
                textProp.stringValue = text;
                so.ApplyModifiedProperties();
            }

            return;
        }
    }

    private static IEnumerable<SerializedProperty> IterateRefIds(SerializedProperty refIds)
    {
        for (int i = 0; i < refIds.arraySize; i++)
        {
            yield return refIds.GetArrayElementAtIndex(i);
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

namespace EggRescue
{
    public sealed class InteractionPointVfx : MonoBehaviour
    {
        public string pointId;
        public GameObject targetVfx;

        static readonly Dictionary<string, InteractionPointVfx> Discoverers = new Dictionary<string, InteractionPointVfx>();
        static readonly HashSet<string> Discovered = new HashSet<string>();

        public static IEnumerable<string> DiscoveredIds { get { return Discovered; } }

        string Id
        {
            get { return string.IsNullOrEmpty(pointId) ? gameObject.name : pointId; }
        }

        void Start()
        {
            Discoverers[Id] = this;
            SetVisible(!Discovered.Contains(Id));
        }

        void OnDestroy()
        {
            InteractionPointVfx existing;
            if (Discoverers.TryGetValue(Id, out existing) && existing == this)
                Discoverers.Remove(Id);
        }

        public void Discover()
        {
            Discovered.Add(Id);
            SetVisible(false);
        }

        public static void DiscoverFrom(GameObject go)
        {
            if (go == null) return;
            var id = go.name;
            InteractionPointVfx ctrl;
            if (Discoverers.TryGetValue(id, out ctrl) && ctrl != null)
            {
                ctrl.Discover();
                return;
            }
            if (Discovered.Contains(id)) return;
            var yellow = go.transform.Find("VFX_InteractionPoint");
            var pink = go.transform.Find("VFX_InteractionPoint_Pink");
            var vfx = yellow != null ? yellow.gameObject : (pink != null ? pink.gameObject : null);
            if (vfx != null)
            {
                vfx.SetActive(false);
                Discovered.Add(id);
            }
            var self = go.GetComponent<InteractionPointVfx>();
            if (self != null) self.Discover();
        }

        public static void MarkDiscovered(string id)
        {
            if (!string.IsNullOrEmpty(id)) Discovered.Add(id);
        }

        public static void ClearDiscovered()
        {
            Discovered.Clear();
        }

        void SetVisible(bool visible)
        {
            var vfx = targetVfx;
            if (vfx == null)
            {
                var yellow = transform.Find("VFX_InteractionPoint");
                var pink = transform.Find("VFX_InteractionPoint_Pink");
                vfx = yellow != null ? yellow.gameObject : (pink != null ? pink.gameObject : null);
            }
            if (vfx == null) return;
            vfx.SetActive(visible);
            if (!visible) return;
            var systems = vfx.GetComponentsInChildren<ParticleSystem>(true);
            for (var i = 0; i < systems.Length; i++)
            {
                systems[i].Clear(true);
