using System;
using System.IO;
using UnityEditor;
using UnityEngine;
using UnityEngine.Rendering;

// Rebuild only the four authored effects; existing prefab/component IDs are preserved.
public static class CartoonVfxPolish
{
    const string Root = "Assets/Res/vfx/";
    static Material dot, star, ring;
    static readonly Color Gold = new Color(1f, .71f, .16f);
    static readonly Color Pink = new Color(1f, .36f, .62f);
    static readonly Color Mint = new Color(.25f, .85f, .68f);
    static readonly Color Cream = new Color(1f, .92f, .64f);

    [MenuItem("EggRescue/VFX/Apply Cartoon Polish")]
    public static void Apply()
    {
        dot = MakeMaterial("Dot", 0);
        star = MakeMaterial("Star", 1);
        ring = MakeMaterial("Ring", 2);
        Edit("vfx_characterChange", Character);
        Edit("vfx_interact", Interact);
        Edit("VFX_InteractionPoint", go => Point(go, Gold));
        Edit("VFX_InteractionPoint_Pink", go => Point(go, Pink));
        AssetDatabase.SaveAssets();
        Debug.Log("Cartoon VFX polish complete: four prefabs saved.");
    }

    static void Edit(string name, Action<GameObject> edit)
    {
        string path = Root + "prefabs/" + name + ".prefab";
        var go = PrefabUtility.LoadPrefabContents(path);
        try { edit(go); PrefabUtility.SaveAsPrefabAsset(go, path); }
        finally { PrefabUtility.UnloadPrefabContents(go); }
    }

    static Material MakeMaterial(string name, int shape)
    {
        string texturePath = Root + "textures/t_cartoon" + name + ".png";
        const int size = 128, samples = 4;
        var tex = new Texture2D(size, size, TextureFormat.RGBA32, false);
        for (int y = 0; y < size; y++)
        for (int x = 0; x < size; x++)
        {
            float coverage = 0;
            for (int sy = 0; sy < samples; sy++)
            for (int sx = 0; sx < samples; sx++)
            {
                float u = ((x + (sx + .5f) / samples) / size - .5f) * 2;
                float v = ((y + (sy + .5f) / samples) / size - .5f) * 2;
                float r = Mathf.Sqrt(u * u + v * v);
                bool inside = shape == 0 ? r < .84f : shape == 2 ? r < .9f && r > .68f
                    : Mathf.Pow(Mathf.Abs(u) / .9f, .7f) + Mathf.Pow(Mathf.Abs(v) / .9f, .7f) < 1;
                if (inside) coverage += 1f / (samples * samples);
            }
            tex.SetPixel(x, y, new Color(1, 1, 1, coverage));
        }
        tex.Apply();
        File.WriteAllBytes(texturePath, tex.EncodeToPNG());
        UnityEngine.Object.DestroyImmediate(tex);
        AssetDatabase.ImportAsset(texturePath);
        var importer = (TextureImporter)AssetImporter.GetAtPath(texturePath);
        importer.alphaIsTransparency = true;
        importer.mipmapEnabled = false;
        importer.wrapMode = TextureWrapMode.Clamp;
        importer.textureCompression = TextureImporterCompression.Uncompressed;
        importer.SaveAndReimport();
        string path = Root + "mats/m_cartoon" + name + ".mat";
        var mat = AssetDatabase.LoadAssetAtPath<Material>(path);
        if (mat == null)
        {
            mat = new Material(Shader.Find("Universal Render Pipeline/Particles/Unlit"));
            AssetDatabase.CreateAsset(mat, path);
        }
        mat.SetTexture("_BaseMap", AssetDatabase.LoadAssetAtPath<Texture2D>(texturePath));
        mat.SetColor("_BaseColor", Color.white);
        mat.SetFloat("_Surface", 1);
        mat.SetFloat("_Blend", 0);
        mat.SetFloat("_ColorMode", 0);
        mat.SetFloat("_SrcBlend", (float)BlendMode.SrcAlpha);
        mat.SetFloat("_DstBlend", (float)BlendMode.OneMinusSrcAlpha);
        mat.SetFloat("_SrcBlendAlpha", (float)BlendMode.One);
        mat.SetFloat("_DstBlendAlpha", (float)BlendMode.OneMinusSrcAlpha);
        mat.SetFloat("_ZWrite", 0);
        mat.SetFloat("_Cull", 0);
        mat.SetFloat("_SoftParticlesEnabled", 0);
        mat.SetFloat("_CameraFadingEnabled", 0);
        mat.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");
        mat.DisableKeyword("_ALPHAPREMULTIPLY_ON");
        mat.DisableKeyword("_ALPHAMODULATE_ON");
        mat.SetOverrideTag("RenderType", "Transparent");
        mat.SetShaderPassEnabled("ShadowCaster", false);
        mat.SetShaderPassEnabled("DepthOnly", false);
        mat.renderQueue = 3000;
        EditorUtility.SetDirty(mat);
        return mat;
    }

    static ParticleSystem Layer(GameObject root, string name)
    {
        var t = root.transform.Find(name);
        if (t == null) { t = new GameObject(name).transform; t.SetParent(root.transform, false); }
        var ps = t.GetComponent<ParticleSystem>();
        return ps != null ? ps : t.gameObject.AddComponent<ParticleSystem>();
    }

    static void Setup(ParticleSystem ps, Material mat, Color color, float duration, bool loop,
        float life, float size, float speed, float radius, params ParticleSystem.Burst[] bursts)
    {
        ps.Stop(true, ParticleSystemStopBehavior.StopEmittingAndClear);
        ps.transform.localRotation = Quaternion.identity;
        ps.transform.localPosition = Vector3.zero;
        ps.transform.localScale = Vector3.one;
        var main = ps.main;
        main.duration = duration; main.loop = loop; main.prewarm = false;
        main.playOnAwake = true; main.startDelay = 0; main.simulationSpeed = 1;
        main.simulationSpace = ParticleSystemSimulationSpace.Local;
        main.scalingMode = ParticleSystemScalingMode.Hierarchy;
        main.startLifetime = new ParticleSystem.MinMaxCurve(life * .85f, life);
        main.startSpeed = new ParticleSystem.MinMaxCurve(speed * .7f, speed);
        main.startSize3D = false; main.startSize = new ParticleSystem.MinMaxCurve(size * .8f, size);
        main.startRotation3D = false; main.startRotation = new ParticleSystem.MinMaxCurve(-.45f, .45f);
        main.startColor = color; main.gravityModifier = 0;
        main.maxParticles = loop ? 24 : 64;
        var emission = ps.emission; emission.enabled = true;
        emission.rateOverTime = 0; emission.rateOverDistance = 0; emission.SetBursts(bursts);
        var shape = ps.shape; shape.enabled = radius > 0; shape.shapeType = ParticleSystemShapeType.Sphere;
        shape.radius = radius; shape.radiusThickness = .65f;
        shape.position = Vector3.zero; shape.rotation = Vector3.zero; shape.scale = Vector3.one;
        var velocity = ps.velocityOverLifetime; velocity.enabled = false;
        var force = ps.forceOverLifetime; force.enabled = false;
        var noise = ps.noise; noise.enabled = false;
        var limit = ps.limitVelocityOverLifetime; limit.enabled = false;
        var inherit = ps.inheritVelocity; inherit.enabled = false;
        var rotation = ps.rotationOverLifetime; rotation.enabled = true; rotation.separateAxes = false;
        rotation.z = new ParticleSystem.MinMaxCurve(-.8f, .8f);
        var sizeOver = ps.sizeOverLifetime; sizeOver.enabled = true; sizeOver.separateAxes = false;
        sizeOver.size = new ParticleSystem.MinMaxCurve(1, Curve(0, .15f, .14f, 1.12f, .32f, .92f, .7f, .8f, 1, 0));
        var tint = ps.colorOverLifetime; tint.enabled = true;
        var gradient = new Gradient();
        gradient.SetKeys(new[] { new GradientColorKey(Color.white, 0), new GradientColorKey(Color.white, 1) },
            new[] { new GradientAlphaKey(1, 0), new GradientAlphaKey(1, .75f), new GradientAlphaKey(0, 1) });
        tint.color = gradient;
        var trails = ps.trails; trails.enabled = false;
        var texture = ps.textureSheetAnimation; texture.enabled = false;
        var sizeSpeed = ps.sizeBySpeed; sizeSpeed.enabled = false;
        var colorSpeed = ps.colorBySpeed; colorSpeed.enabled = false;
        var rotationSpeed = ps.rotationBySpeed; rotationSpeed.enabled = false;
        var renderer = ps.GetComponent<ParticleSystemRenderer>();
        renderer.sharedMaterial = mat; renderer.renderMode = ParticleSystemRenderMode.Billboard;
        renderer.alignment = ParticleSystemRenderSpace.View;
        renderer.minParticleSize = 0; renderer.maxParticleSize = 1;
        renderer.shadowCastingMode = ShadowCastingMode.Off; renderer.receiveShadows = false;
    }

    static AnimationCurve Curve(params float[] pairs)
    {
        var keys = new Keyframe[pairs.Length / 2];
        for (int i = 0; i < keys.Length; i++) keys[i] = new Keyframe(pairs[i * 2], pairs[i * 2 + 1]);
        return new AnimationCurve(keys);
    }
    static ParticleSystem.Burst Beat(float time, short count) { return new ParticleSystem.Burst(time, count); }
    static void Ripple(ParticleSystem ps, Color color, float duration, bool loop, float size, float time)
    {
        Setup(ps, ring, color, duration, loop, .6f, size, 0, 0, Beat(time, 1));
        var main = ps.main; main.startRotation = 0;
        var s = ps.sizeOverLifetime;
        s.size = new ParticleSystem.MinMaxCurve(1, Curve(0, .3f, .25f, .7f, .7f, 1, 1, 1.08f));
        var c = ps.colorOverLifetime;
        var g = new Gradient();
        g.SetKeys(new[] { new GradientColorKey(Color.white, 0), new GradientColorKey(Color.white, 1) },
            new[] { new GradientAlphaKey(.85f, 0), new GradientAlphaKey(.85f, .5f), new GradientAlphaKey(0, 1) });
        c.color = g;
    }
    static void Character(GameObject go)
    {
        Setup(go.GetComponent<ParticleSystem>(), dot, Mint, 1.25f, false, .55f, .42f, 1.15f, .32f, Beat(0, 10), Beat(.12f, 6));
        Setup(Layer(go, "Sparkles"), star, Gold, 1.25f, false, .68f, .31f, 1.65f, .25f, Beat(.12f, 9));
        Ripple(Layer(go, "Ripple"), Cream, 1.25f, false, 1.85f, .06f);
        Setup(Layer(go, "Motes"), dot, Cream, 1.25f, false, .55f, .12f, .65f, .55f, Beat(.3f, 7));
        foreach (var ps in go.GetComponentsInChildren<ParticleSystem>()) ps.transform.localPosition = new Vector3(0, .65f, 0);
        go.transform.localPosition = Vector3.zero;
        var shape = go.GetComponent<ParticleSystem>().shape; shape.position = new Vector3(0, .65f, 0);
    }
    static void Interact(GameObject go)
    {
        Setup(go.GetComponent<ParticleSystem>(), star, Gold, .8f, false, .42f, .26f, 1.2f, .1f, Beat(0, 6));
        Setup(Layer(go, "vfx_interact (1)"), dot, Cream, .8f, false, .35f, .11f, .85f, .15f, Beat(.1f, 5));
        Ripple(Layer(go, "vfx_interact (2)"), Gold, .8f, false, .95f, 0);
    }
    static void Point(GameObject go, Color color)
    {
        Setup(go.GetComponent<ParticleSystem>(), star, color, 1.8f, true, .82f, .28f, .17f, .23f, Beat(0, 3), Beat(.3f, 2));
        var shape = go.GetComponent<ParticleSystem>().shape; shape.position = new Vector3(0, .4f, 0);
        Setup(Layer(go, "CandyDots"), dot, color, 1.8f, true, .65f, .085f, .24f, .26f, Beat(.16f, 3), Beat(.46f, 2));
        var dots = go.transform.Find("CandyDots"); dots.localPosition = new Vector3(0, .35f, 0);
        Ripple(Layer(go, "PulseRing"), color, 1.8f, true, .68f, 0);
        go.transform.Find("PulseRing").localPosition = new Vector3(0, .35f, 0);
    }
}

from pathlib import Path
import re, uuid, math, struct, zlib, binascii
R=Path('Assets/Res/vfx')
def field(s,key,val,indent=2):
    pat=rf'(?m)^{{indent}}' # exact scalar replacement only
    pat=r'(?m)^'+(' '*indent)+re.escape(key)+r':[^\n]*$'
    s,n=re.subn(pat,' '*indent+key+': '+str(val),s)
    assert n==1,(key,n)
    return s
def block(s,key,fn,indent=2):
    pat=r'(?m)^'+(' '*indent)+re.escape(key)+r':\n(?:^ {'+str(indent+1)+r',}[^\n]*\n|^ *\n)*'
    m=re.search(pat,s); assert m,key
    return s[:m.start()]+fn(m.group())+s[m.end():]
def mm(s,key,lo,hi=None,indent=4):
    hi=lo if hi is None else hi
    def run(b):
        for k,v in [('minMaxState',0 if lo==hi else 3),('scalar',hi),('minScalar',lo)]: b=field(b,k,v,indent+2)
        return b
    return block(s,key,run,indent)
def curve(s,key,points,indent=4):
    def run(b):
        b=field(b,'minMaxState',1,indent+2); b=field(b,'scalar',1,indent+2)
        def keys(c):
            pad=' '*(indent+4)
            text=pad+'m_Curve:\n'
            for t,v in points:
                text+=pad+'- serializedVersion: 3\n'
                for k,value in [('time',t),('value',v),('inSlope',0),('outSlope',0),('tangentMode',0),('weightedMode',0),('inWeight',.33333334),('outWeight',.33333334)]:
                    text+=pad+'  '+k+': '+str(value)+'\n'
            return re.sub(r'(?m)^ *m_Curve:\n.*?(?=^ *m_PreInfinity:)',lambda m:text,c,flags=re.S)
        return block(b,'maxCurve',keys,indent+2)
    return block(s,key,run,indent)
def rgba(c): return '{r: %s, g: %s, b: %s, a: %s}'%tuple(c)
def tint(s,key,c,indent=4):
    def run(b):
        b=field(b,'minMaxState',0,indent+2)
        for k in ['minColor','maxColor']: b=field(b,k,rgba(c),indent+2)
        return b
    return block(s,key,run,indent)
def gradient(s,ring=False):
    def run(b):
        b=field(b,'enabled',1,4)
        def grad(g):
            g=field(g,'minMaxState',1,6)
            def keys(k):
                for i,a in enumerate([.85 if ring else 1,.85 if ring else 1,0]): k=field(k,'key'+str(i),rgba([1,1,1,a]),8)
                for i,t in enumerate([0,32768 if ring else 49151,65535]): k=field(k,'atime'+str(i),t,8)
                k=field(k,'m_NumAlphaKeys',3,8)
                return k
            return block(g,'maxGradient',keys,6)
        return block(b,'gradient',grad,4)
    return block(s,'ColorModule',run)

guids={}
for name,shape in [('Dot',0),('Star',1),('Ring',2)]:
    tex=R/'textures'/('t_cartoon'+name+'.png'); tg=uuid.uuid4().hex; mg=uuid.uuid4().hex; guids[name]=mg
    raw=bytearray()
    for y in range(128):
        raw.append(0)
        for x in range(128):
            coverage=0
            for sy in range(4):
                for sx in range(4):
                    u=((x+(sx+.5)/4)/128-.5)*2; v=((y+(sy+.5)/4)/128-.5)*2; r=math.hypot(u,v)
                    inside=r<.84 if shape==0 else .68<r<.9 if shape==2 else (abs(u)/.9)**.7+(abs(v)/.9)**.7<1
                    coverage+=inside
            raw.extend([255,255,255,round(coverage/16*255)])
    def chunk(tag,data): return struct.pack('>I',len(data))+tag+data+struct.pack('>I',binascii.crc32(tag+data)&0xffffffff)
    tex.write_bytes(b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack('>IIBBBBB',128,128,8,6,0,0,0))+chunk(b'IDAT',zlib.compress(bytes(raw)))+chunk(b'IEND',b''))
    meta=(R/'textures/t_starTexture.png.meta').read_text()
    meta=re.sub(r'guid: [a-f0-9]+','guid: '+tg,meta,count=1)
    for k,v in [('enableMipMap',0),('textureCompression',0),('wrapU',1),('wrapV',1),('alphaIsTransparency',1)]: meta=re.sub(r'(?m)^(\s*'+k+r':) .+$',r'\g<1> '+str(v),meta)
    Path(str(tex)+'.meta').write_text(meta)
    mat=(R/'mats/m_starParticle.mat').read_text(); mat=mat.split('--- !u!114')[0]
    mat=field(mat,'m_Name','m_cartoon'+name); mat=mat.replace('9a9cc036c3d5745a09428d3ef39e7fbc',tg)
    for k,v in [('_Blend',0),('_DstBlend',10),('_DstBlendAlpha',10),('_Cull',0)]: mat=re.sub(r'(?m)^(    - '+k+r':) .+$',r'\g<1> '+str(v),mat)
    p=R/'mats'/('m_cartoon'+name+'.mat'); p.write_text(mat)
    Path(str(p)+'.meta').write_text('fileFormatVersion: 2\nguid: '+mg+'\nNativeFormatImporter:\n  externalObjects: {}\n  mainObjectFileID: 2100000\n  userData: \n  assetBundleName: \n  assetBundleVariant: \n')

source=(R/'prefabs/vfx_characterChange.prefab').read_text()
burst_template=re.search(r'    - serializedVersion: 2\n      time: 0\n      countCurve:.*?      probability: 1\n',source,re.S).group()
def tune(s,mat,color,duration,loop,life,size,speed,radius,beats,isring=False,height=0):
    for k,v in [('lengthInSec',duration),('looping',int(loop)),('prewarm',0),('simulationSpeed',1),('moveWithTransform',1),('scalingMode',0)]: s=field(s,k,v)
    s=mm(s,'startDelay',0,indent=2)
    def initial(b):
        for key,lo,hi in [('startLifetime',life*.85,life),('startSpeed',speed*.7,speed),('startSize',size*.8,size),('startRotation',-.45 if not isring else 0,.45 if not isring else 0),('gravityModifier',0,0)]: b=mm(b,key,lo,hi)
        b=tint(b,'startColor',color); b=field(b,'maxNumParticles',24 if loop else 64,4)
        return b
    s=block(s,'InitialModule',initial)
    def shape(b):
        for k,v in [('enabled',int(radius>0)),('type',0),('radiusThickness',.65),('m_Position','{x: 0, y: '+str(height)+', z: 0}'),('m_Rotation','{x: 0, y: 0, z: 0}'),('m_Scale','{x: 1, y: 1, z: 1}')]: b=field(b,k,v,4)
        return mm(b,'radius',radius)
    s=block(s,'ShapeModule',shape)
    def emission(b):
        b=mm(b,'rateOverTime',0); b=mm(b,'rateOverDistance',0)
        b=b[:b.index('    m_BurstCount:')]+f'    m_BurstCount: {len(beats)}\n    m_Bursts:\n'
        for time,count in beats:
            burst=field(burst_template,'time',time,6); burst=mm(burst,'countCurve',count,indent=6); b+=burst
        return b
    s=block(s,'EmissionModule',emission)
    for mod in ['VelocityModule','ForceModule','NoiseModule','ClampVelocityModule','InheritVelocityModule','UVModule','TrailModule','SizeBySpeedModule','ColorBySpeedModule','RotationBySpeedModule']:
        s=block(s,mod,lambda b:field(b,'enabled',0,4))
    points=[(0,.3),(.25,.7),(.7,1),(1,1.08)] if isring else [(0,.15),(.14,1.12),(.32,.92),(.7,.8),(1,0)]
    s=block(s,'SizeModule',lambda b:curve(field(field(b,'enabled',1,4),'separateAxes',0,4),'curve',points))
    s=block(s,'RotationModule',lambda b:mm(field(b,'enabled',int(not isring),4),'curve',-.8,.8))
    return gradient(s,isring)

Gold=[1,.71,.16,1]; Pink=[1,.36,.62,1]; Mint=[.25,.85,.68,1]; Cream=[1,.92,.64,1]
for name in ['vfx_characterChange','vfx_interact','VFX_InteractionPoint','VFX_InteractionPoint_Pink']:
    p=R/'prefabs'/(name+'.prefab'); text=p.read_text(); docs=re.split(r'(?=^--- !u!)',text,flags=re.M)
    point=name.startswith('VFX_'); char=name=='vfx_characterChange'; color=Pink if name.endswith('Pink') else Gold
    if point:
        # Duplicate the existing complete system while assigning new local IDs.
        original=docs[1:]; rootTransform=re.search(r'&(-?\d+)',original[1]).group(1)
        for layer,label in enumerate(['CandyDots','PulseRing']):
            ids=re.findall(r'^--- !u!\d+ &(-?\d+)', ''.join(original),re.M)
            mapping={id:str(820000+layer*10+i) for i,id in enumerate(ids)}
            clone=''.join(original)
            for old,new in mapping.items(): clone=re.sub(r'(?<!\d)'+old+r'(?!\d)',new,clone)
            clone=clone.replace('m_Name: '+name,'m_Name: '+label)
            clone=clone.replace('m_Father: {fileID: 0}','m_Father: {fileID: '+rootTransform+'}')
            clone=clone.replace('m_LocalPosition: {x: 0, y: 0, z: 0}','m_LocalPosition: {x: 0, y: 0.35, z: 0}')
            docs.extend(re.split(r'(?=^--- !u!)',clone,flags=re.M)[1:])
        docs[2]=docs[2].replace('m_Children: []','m_Children:\n  - {fileID: 820001}\n  - {fileID: 820011}')
        specs=[('Star',color,1.8,True,.82,.28,.17,.23,[(0,3),(.3,2)],False,.4),('Dot',color,1.8,True,.65,.085,.24,.26,[(.16,3),(.46,2)],False,0),('Ring',color,1.8,True,.6,.68,0,0,[(0,1)],True,0)]
    elif char:
        specs=[('Dot',Mint,1.25,False,.55,.42,1.15,.32,[(0,10),(.12,6)],False,.65),('Star',Gold,1.25,False,.68,.31,1.65,.25,[(.12,9)],False,0),('Ring',Cream,1.25,False,.6,1.85,0,0,[(.06,1)],True,0),('Dot',Cream,1.25,False,.55,.12,.65,.55,[(.3,7)],False,0)]
    else:
        specs=[('Star',Gold,.8,False,.42,.26,1.2,.1,[(0,6)],False,0),('Dot',Cream,.8,False,.35,.11,.85,.15,[(.1,5)],False,0),('Ring',Gold,.8,False,.6,.95,0,0,[(0,1)],True,0)]
    pi=ri=ti=0
    for i,d in enumerate(docs):
        if d.startswith('--- !u!198 '): docs[i]=tune(d,*specs[pi]); pi+=1
        elif d.startswith('--- !u!199 '):
            d=re.sub(r'(m_Materials:\n  - \{fileID: 2100000, guid: )[a-f0-9]+',lambda m:m[1]+guids[specs[ri][0]],d)
            for k,v in [('m_RenderMode',0),('m_RenderAlignment',0),('m_MaxParticleSize',1)]: d=field(d,k,v)
            docs[i]=d; ri+=1
        elif d.startswith('--- !u!4 '):
            d=field(d,'m_LocalRotation','{x: 0, y: 0, z: 0, w: 1}')
            d=field(d,'m_LocalEulerAnglesHint','{x: 0, y: 0, z: 0}')
            if not point: d=field(d,'m_LocalPosition','{x: 0, y: '+str(.65 if char and ti>0 else 0)+', z: 0}')
            docs[i]=d; ti+=1
    assert pi==ri==len(specs)
    p.write_text(''.join(docs))
    print(name,pi,'particle systems saved')

