from pathlib import Path
import re
root=Path('Assets/Res/vfx')
p=root/'prefabs/VFX_InteractionPoint_Pink.prefab'
s=p.read_text()
s=re.sub(r'(propertyPath: m_LocalPosition\.[xyz]\n      value:) [^\n]+',r'\1 0',s)
for ch,val in [('r',1),('g',.36),('b',.62)]:
    s=re.sub(r'(propertyPath: InitialModule.startColor.(?:min|max)Color\.'+ch+r'\n      value:) [^\n]+',r'\g<1> '+str(val),s)
extra=''
for id in [820002,820012]:
    for mode in ['minColor','maxColor']:
        for ch,val in [('r',1),('g',.36),('b',.62),('a',1)]:
            extra+=f'    - target: {{fileID: {id}, guid: c1a6ed9270ed8e141b7c0906814c4cf0, type: 3}}\n      propertyPath: InitialModule.startColor.{mode}.{ch}\n      value: {val}\n      objectReference: {{fileID: 0}}\n'
s=s.replace('    m_RemovedComponents:',extra+'    m_RemovedComponents:')
p.write_text(s)
# Keep serialized floats readable, without altering any IDs or asset references.
for p in (root/'prefabs').glob('*.prefab'):
    if p.stem not in ['vfx_characterChange','vfx_interact','VFX_InteractionPoint','VFX_InteractionPoint_Pink']: continue
    s=p.read_text(); s=re.sub(r'(?<=: )-?\d+\.\d{9,}',lambda m:format(float(m[0]),'.8g'),s); p.write_text(s)

# Validate references, inherited pink overrides, module boundaries, curves and particle budgets.
assets={re.search(r'^guid: (\w+)',p.read_text(),re.M)[1]:p for p in root.rglob('*.meta') if re.search(r'^guid: (\w+)',p.read_text(),re.M)}
for name,n in [('vfx_characterChange',4),('vfx_interact',3),('VFX_InteractionPoint',3)]:
    s=(root/'prefabs'/(name+'.prefab')).read_text()
    ids=re.findall(r'^--- !u!\d+ &(-?\d+)',s,re.M); assert len(ids)==len(set(ids))
    for line in s.splitlines():
        if 'guid:' not in line:
            for id in re.findall(r'fileID: (-?\d+)',line): assert id=='0' or id in ids,(name,id)
    for guid in re.findall(r'guid: (\w+)',s): assert guid in assets,(name,guid)
    docs=re.findall(r'^--- !u!198 .*?(?=^--- !u!|\Z)',s,re.M|re.S); assert len(docs)==n
    for d in docs:
        assert len(re.findall(r'^  InitialModule:',d,re.M))==1
        for mod in ['ShapeModule','EmissionModule','SizeModule','RotationModule','ColorModule','UVModule','VelocityModule','TrailModule']:
            assert len(re.findall(r'^  '+mod+':',d,re.M))==1
        count=int(re.search(r'm_BurstCount: (\d+)',d)[1]); assert count==len(re.findall('      probability: 1',d))
        assert re.search(r'maxNumParticles: (24|64)',d)
    print('PASS',name, 'systems:',len(docs),'unique object IDs:',len(ids))
s=p.read_text() if False else (root/'prefabs/VFX_InteractionPoint_Pink.prefab').read_text()
base=(root/'prefabs/VFX_InteractionPoint.prefab').read_text()
for id in re.findall(r'target: \{fileID: (\d+)',s): assert '&'+id+'\n' in base
assert s.count('value: 0.36')==6 and s.count('value: 0.62')==6
print('PASS pink variant: all three layers inherit timing and override to pink')
for shape in ['Dot','Star','Ring']:
    s=(root/'mats'/('m_cartoon'+shape+'.mat')).read_text()
    assert '_DstBlend: 10' in s and '_Blend: 0' in s and '_SrcBlend: 5' in s
    guid=re.search(r'_BaseMap:\n        m_Texture: \{fileID: 2800000, guid: (\w+)',s)[1]; assert guid in assets
print('PASS three dedicated alpha-blended materials and texture references')

