from pathlib import Path
import ast, re

# Reuse only pure serialization helpers, never rerun the earlier asset generator.
source=Path('Temp/polish_vfx.py').read_text()
tree=ast.parse(source)
exec(compile(ast.Module(body=[n for n in tree.body if isinstance(n,ast.FunctionDef)],type_ignores=[]),'<vfx helpers>','exec'))
root=Path('Assets/Res/vfx')
character=(root/'prefabs/vfx_characterChange.prefab').read_text()
burst_template=re.search(r'    - serializedVersion: 2\n      time: 0\n      countCurve:.*?      probability: 1\n',character,re.S)[0]
guids={name:re.search(r'guid: (\w+)',(root/f'mats/m_cartoon{name}.mat.meta').read_text())[1] for name in ['Dot','Star','Ring']}
gold=[1,.71,.16,1]; mint=[.25,.85,.68,1]; cream=[1,.92,.64,1]
def split(s): return re.split(r'(?=^--- !u!)',s,flags=re.M)
def save(path,s):
    s=re.sub(r'(?<=: )-?\d+\.\d{9,}',lambda m:format(float(m[0]),'.8g'),s)
    path.write_text(s,encoding='utf-8')
def renderer(d,mat,horizontal=False):
    d=re.sub(r'(m_Materials:\n  - \{fileID: 2100000, guid: )[a-f0-9]+',lambda m:m[1]+guids[mat],d)
    for k,v in [('m_RenderMode',2 if horizontal else 0),('m_RenderAlignment',0),('m_MaxParticleSize',1)]: d=field(d,k,v)
    return d

# Preserve all existing component IDs and user-authored dimensions; speed up the whole timeline.
for name in ['vfx_characterChange','vfx_interact','VFX_InteractionPoint']:
    p=root/f'prefabs/{name}.prefab'; s=p.read_text()
    s,n=re.subn(r'(?m)^  simulationSpeed: [^\n]+','  simulationSpeed: 1.2',s)
    assert n in [3,4]; save(p,s)
# Pink is a prefab variant: inherits the three accelerated systems without overrides.

point=split((root/'prefabs/VFX_InteractionPoint.prefab').read_text())
template=''.join(point[1:5])
def layer(name,base,parent,spec,pos=(0,0,0),horizontal=False,persistent=False):
    s=template
    ids=re.findall(r'^--- !u!\d+ &(-?\d+)',s,re.M)
    mapping={old:str(base+i) for i,old in enumerate(ids)}
    for old,new in mapping.items(): s=re.sub(r'(?<!\d)'+old+r'(?!\d)',new,s)
    docs=split(s)
    for i,d in enumerate(docs):
        if d.startswith('--- !u!1 '): docs[i]=field(d,'m_Name',name)
        elif d.startswith('--- !u!4 '):
            d=re.sub(r'  m_Children:\n(?:  - \{fileID: \d+\}\n)+','  m_Children: []\n',d)
            d=field(d,'m_Father','{fileID: '+str(parent)+'}')
            d=field(d,'m_LocalPosition','{x: %s, y: %s, z: %s}'%pos)
            docs[i]=d
        elif d.startswith('--- !u!198 '):
            d=field(tune(d,*spec),'simulationSpeed',1.2)
            if persistent:
                d=block(d,'InitialModule',lambda b:mm(mm(b,'startLifetime',1.5),'startSize',1.05))
                d=block(d,'SizeModule',lambda b:curve(b,'curve',[(0,.86),(.12,1),(.3,.9),(.43,.98),(.7,.88),(1,.86)]))
                d=block(d,'ColorModule',lambda b:field(b,'enabled',0,4))
            docs[i]=d
        elif d.startswith('--- !u!199 '): docs[i]=renderer(d,spec[0],horizontal)
    return ''.join(docs)

p=root/'prefabs/starParticle.prefab'; docs=split(p.read_text())
spec=('Star',gold,1.4,True,.64,.25,.22,.28,[(0,4),(.24,2)],False,.3)
for i,d in enumerate(docs):
    if d.startswith('--- !u!198 '): docs[i]=field(tune(d,*spec),'simulationSpeed',1.2)
    elif d.startswith('--- !u!199 '): docs[i]=renderer(d,'Star')
    elif d.startswith('--- !u!4 '):
        for k,v in [('m_LocalRotation','{x: 0, y: 0, z: 0, w: 1}'),('m_LocalPosition','{x: 0, y: 0, z: 0}'),('m_LocalEulerAnglesHint','{x: 0, y: 0, z: 0}')]: d=field(d,k,v)
        docs[i]=d.replace('  m_Children: []','  m_Children:\n  - {fileID: 830001}')
s=''.join(docs)+layer('CandyDots',830000,8993947849949628402,('Dot',cream,1.4,True,.5,.085,.3,.25,[(.1,3),(.34,2)],False,0),(0,.3,0))
save(p,s)

p=root/'prefabs/targetVfx.prefab'; docs=split(p.read_text()); parent=8571255122768210375
for i,d in enumerate(docs):
    if d.startswith('--- !u!198 '): docs[i]=field(tune(d,'Star',mint,1.5,True,.6,.2,.22,.35,[(.06,3),(.3,2)],False,.3),'simulationSpeed',1.2)
    elif d.startswith('--- !u!199 '): docs[i]=renderer(d,'Star')
    elif d.startswith('--- !u!95 '): docs[i]=field(d,'m_Enabled',0) # Particle curves now drive the bounce, without scaling the entire marker.
    elif d.startswith('--- !u!4 ') and ' stripped' not in d:
        for k,v in [('m_LocalRotation','{x: 0, y: 0, z: 0, w: 1}'),('m_LocalPosition','{x: 0, y: 0, z: 0}'),('m_LocalEulerAnglesHint','{x: 0, y: 0, z: 0}')]: d=field(d,k,v)
        if '&'+str(parent)+'\n' in d: d=d.replace('  m_Father:', '  - {fileID: 840001}\n  - {fileID: 840011}\n  - {fileID: 840021}\n  m_Father:')
        docs[i]=d
    elif d.startswith('--- !u!1001 '):
        guid=re.search(r'm_SourcePrefab:.*guid: (\w+)',d)[1]
        override=f'    - target: {{fileID: -7511558181221131132, guid: {guid}, type: 3}}\n      propertyPath: m_Enabled\n      value: 0\n      objectReference: {{fileID: 0}}\n'
        docs[i]=d.replace('    m_RemovedComponents:',override+'    m_RemovedComponents:')
s=''.join(docs)
s+=layer('GroundRing',840000,parent,('Ring',mint,1.5,True,1.5,1.05,0,0,[(0,1)],True,0),(0,.035,0),True,True)
s+=layer('PulseRing',840010,parent,('Ring',cream,1.5,True,.6,1.4,0,0,[(.16,1)],True,0),(0,.045,0),True)
s+=layer('CandyDots',840020,parent,('Dot',gold,1.5,True,.55,.085,.3,.38,[(.14,4),(.38,2)],False,0),(0,.18,0))
save(p,s)
print('Saved starParticle, targetVfx and 1.2x playback for the previous effects; pink inherits playback.')

# Structural checks on new hierarchies and all modified particle timelines.
for name,expected in [('starParticle',2),('targetVfx',4),('vfx_characterChange',4),('vfx_interact',3),('VFX_InteractionPoint',3)]:
    s=(root/f'prefabs/{name}.prefab').read_text(); ids=re.findall(r'^--- !u!\d+ &(-?\d+)',s,re.M)
    assert len(ids)==len(set(ids)),name
    for line in s.splitlines():
        if 'guid:' not in line:
            for id in re.findall(r'fileID: (-?\d+)',line): assert id=='0' or id in ids,(name,id)
    systems=re.findall(r'^--- !u!198 .*?(?=^--- !u!|\Z)',s,re.S|re.M)
    assert len(systems)==expected
    for ps in systems:
        assert '  simulationSpeed: 1.2\n' in ps
        assert int(re.search(r'm_BurstCount: (\d+)',ps)[1])==ps.count('      probability: 1\n')
    print('PASS',name,expected,'systems; IDs, references, bursts and playback speed')
